function({ series, seriesIndex, dataPointIndex, w }) { 

    const formatNumber = (number) => {
        return number.toLocaleString();
    };

    return ( 
        "<div style='padding: 5px'>" +"<b>"+ w.config.labels[seriesIndex]+" </b>"
+formatNumber(series[seriesIndex]/60)+
        " min. </div>"
    );
}

